package com.cyancoder.aiorchestrator.service;
import com.cyancoder.aiorchestrator.domain.*; import com.cyancoder.aiorchestrator.repo.*; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*;
@Service public class ProjectReleaseService{private final ProjectReleaseRepository releases;private final ClientAppDraftRepository drafts;private final ProvisioningRunRepository runs;public ProjectReleaseService(ProjectReleaseRepository r,ClientAppDraftRepository d,ProvisioningRunRepository p){releases=r;drafts=d;runs=p;}
 public List<ProjectRelease> list(String draftId,String tenant,String site){verifyDraft(draftId,tenant,site);return releases.findByDraftIdOrderByCreatedAtDesc(draftId);} public ProjectRelease get(String id,String tenant,String site){return scoped(releases.findByReleaseId(id).orElseThrow(),tenant,site);}
 public ProjectRelease active(String draftId,String tenant,String site){verifyDraft(draftId,tenant,site);return scoped(releases.findFirstByDraftIdAndStatusOrderByActivatedAtDesc(draftId,"ACTIVE").orElseThrow(),tenant,site);}
 public ProjectRelease create(String draftId,String runId,String actor,String tenant,String site){ClientAppDraft d=verifyDraft(draftId,tenant,site);ProvisioningRun run=runs.findByRunId(runId).filter(x->draftId.equals(x.getDraftId())&&x.getStatus()==ProvisioningRunStatus.SUCCESS).orElseThrow(()->new IllegalStateException("A successful provisioning run is required"));ProjectRelease v=new ProjectRelease();v.setReleaseId("release-"+UUID.randomUUID());v.setDraftId(draftId);v.setTenantKey(d.getTenantKey());v.setSiteKey(d.getSiteKey());v.setSourceRevision(d.getRevision());v.setProvisioningRunId(run.getRunId());v.setSnapshot(d.getResolvedDsl());v.setStatus("READY");v.setCreatedBy(actor);v.setCreatedAt(Instant.now());return releases.save(v);}
 public ProjectRelease activate(String id,String tenant,String site){ProjectRelease target=get(id,tenant,site);for(ProjectRelease v:list(target.getDraftId(),tenant,site))if("ACTIVE".equals(v.getStatus())){v.setStatus("SUPERSEDED");releases.save(v);}target.setStatus("ACTIVE");target.setActivatedAt(Instant.now());return releases.save(target);} private ClientAppDraft verifyDraft(String id,String tenant,String site){ClientAppDraft d=drafts.findByDraftId(id).orElseThrow();if(!Objects.equals(d.getTenantKey(),tenant)||!Objects.equals(d.getSiteKey(),blank(site)))throw new NoSuchElementException();return d;}private ProjectRelease scoped(ProjectRelease v,String tenant,String site){if(!Objects.equals(v.getTenantKey(),tenant)||!Objects.equals(v.getSiteKey(),blank(site)))throw new NoSuchElementException();return v;}private String blank(String v){return v==null||v.isBlank()?null:v;} }
